        if (Javaကိရိယာ.ညီစာသား(စကားလုံးစာသား, "NumberFormatException")) အမျိုးအစားကုဒ် = 10;
        if (Javaကိရိယာ.ညီစာသား(စကားလုံးစာသား, "FileNotFoundException: file open failed")) အမျိုးအစားကုဒ် = 12;
        if (Javaကိရိယာ.ညီစာသား(စကားလုံးစာသား, "IOException: stream closed") || Javaကိရိယာ.ညီစာသား(စကားလုံးစာသား, "IOException: read failed") || Javaကိရိယာ.ညီစာသား(စကားလုံးစာသား, "IOException: write failed")) အမျိုးအစားကုဒ် = 11;
